"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21638"],{73220(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formulario_processo.codigo_formato_invalido","status":422,"titulo":"O c\xf3digo do formul\xe1rio n\xe3o tem o formato permitido"},"descricao":{"codigo":"uniplus.selecao.formulario_processo.codigo_formato_invalido","requisitos":[],"oQueAconteceu":["O c\xf3digo de um formul\xe1rio tem formato fechado: come\xe7a com letra mai\xfascula e tem s\xf3 letras mai\xfasculas, d\xedgitos e sublinhados isolados (nunca dois seguidos, nem no fim), com at\xe9 60 caracteres. Exemplos: `INSCRICAO` e `ISENCAO_TAXA`. O c\xf3digo informado n\xe3o segue esse formato; a mensagem repete a regra.","A recusa sai com **422** na grava\xe7\xe3o do formul\xe1rio (`PUT .../formularios/{codigo}`), na aplica\xe7\xe3o de um modelo e na exig\xeancia de documento. Nas consultas, na remo\xe7\xe3o e na grava\xe7\xe3o dos itens e dos termos, o c\xf3digo fora do formato nem chega a ser tratado: a resposta \xe9 **404**, a mesma de um formul\xe1rio que o processo n\xe3o tem."],"comoResolver":["Troque o c\xf3digo por um que siga o formato e repita o pedido. O c\xf3digo n\xe3o muda depois que o formul\xe1rio \xe9 criado, porque a configura\xe7\xe3o publicada cita o formul\xe1rio por ele: escolha um nome que diga o que o formul\xe1rio coleta."],"ondeAparece":["Grava\xe7\xe3o do formul\xe1rio do processo","Aplica\xe7\xe3o de modelo de formul\xe1rio","Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formulario processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);